const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Coastal Sage UCI station (approximate)
  const point = ee.Geometry.Point([-117.843, 33.642]); // Longitude, Latitude
  const geom = point.buffer(100); // Small buffer to ensure pixel coverage

  // 2. Define date ranges
  const janStart = '2013-01-01';
  const janEnd = '2013-01-31';
  const mayStart = '2013-05-01';
  const mayEnd = '2013-05-31';

  // 3. Load ESA CCI Soil Moisture dataset
  const dataset = 'ECMWF/ESA/CCI_DAILY_SOIL_MOISTURE_V03_DAILY';
  const band = 'sm'; // volumetric soil moisture in m3/m3

  // Function to mask invalid values (outside 0-1)
  function maskInvalid(image) {
    const sm = image.select(band);
    const valid = sm.gte(0).and(sm.lte(1)); // valid range
    return image.updateMask(valid);
  }

  // Function to process a month
  function processMonth(startDate, endDate) {
    const col = ee.ImageCollection(dataset)
                  .filterDate(startDate, endDate)
                  .filterBounds(geom)
                  .map(maskInvalid);
    const size = col.size();
    const meanImg = col.mean().select(band);
    // Reduce region to get mean and count
    const stats = meanImg.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geom,
      scale: 1000,
      maxPixels: 1e9
    });
    return {col: col, size: size, stats: stats, meanImg: meanImg};
  }

  // Process January 2013
  const janResult = processMonth(janStart, janEnd);
  const janSize = janResult.size.getInfo();
  const janStats = janResult.stats.getInfo();
  const janMean = janStats[band];
  const janCount = janStats[band + '_count'];

  // Process May 2013
  const mayResult = processMonth(mayStart, mayEnd);
  const maySize = mayResult.size.getInfo();
  const mayStats = mayResult.stats.getInfo();
  const mayMean = mayStats[band];
  const mayCount = mayStats[band + '_count'];

  // 4. Check for missing data (C1)
  if (janSize === 0 || maySize === 0) {
    console.log(`January 2013 Images: ${janSize}`);
    console.log(`May 2013 Images: ${maySize}`);
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Check for no valid pixels (C2)
  if (janCount === 0 || mayCount === 0) {
    console.log(`January 2013 Valid Pixels: ${janCount}`);
    console.log(`May 2013 Valid Pixels: ${mayCount}`);
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Validate results (C3)
  if (janMean === null || mayMean === null ||
      isNaN(janMean) || isNaN(mayMean) ||
      !isFinite(janMean) || !isFinite(mayMean)) {
    console.log(`January 2013 Mean: ${janMean}`);
    console.log(`May 2013 Mean: ${mayMean}`);
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Output intermediate stats and final answer
  console.log(`January 2013: Images: ${janSize}, Mean SM: ${janMean.toFixed(4)}, Valid Pixels: ${janCount}`);
  console.log(`May 2013: Images: ${maySize}, Mean SM: ${mayMean.toFixed(4)}, Valid Pixels: ${mayCount}`);

  // Compare
  if (janMean > mayMean) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
